initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response containing:
        Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/InvalidRequest' and
        Response body containing 'title' element and
        Response Status Code set to 400
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/entityOperations/update'
        method set to 'POST'
        Batch Entity Delete Request with operation set to 'update', Content-Type set to 'application/ld+json', and body set to 'batch/invalid-json-sample.jsonld
}

